use std::fs

fn is_int(s: string) -> bool {
    let mut i = 0
    let mut digits = 0
    for c in s.chars() {
        if c == '-' && i == 0 {
        } else if c >= '0' && c <= '9' {
            digits += 1
        } else {
            return false
        }
        i += 1
    }
    digits > 0
}

fn eval(line: string) -> string {
    let mut st: Vec<int> = []
    for tok in line.split_whitespace() {
        if tok == "+" || tok == "-" || tok == "*" || tok == "/" {
            if st.len() < 2 {
                return "error: underflow"
            }
            let b = st.pop() ?? 0
            let a = st.pop() ?? 0
            if tok == "+" {
                st.push(a + b)
            } else if tok == "-" {
                st.push(a - b)
            } else if tok == "*" {
                st.push(a * b)
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                st.push(a / b)
            }
        } else if is_int(tok) {
            let v: int = tok.parse::<int>().unwrap_or(0)
            st.push(v)
        } else {
            return "error: token"
        }
    }
    if st.len() != 1 {
        return "error: leftover"
    }
    "${st[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim().len() == 0 {
            continue
        }
        println("${eval(line)}")
    }
}

